param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'interface-name-ordinal-comparison-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})}}
$rows=[Collections.Generic.List[object]]::new();$inventories=[Collections.Generic.List[object]]::new()
foreach($typeName in $plan.types){$type=[type]::GetType($typeName,$true);$first=$type.GetInterfaces();$second=$type.GetInterfaces();$names=@($first|ForEach-Object FullName);$sameCanonical=$true;foreach($contract in $first){if(-not [object]::ReferenceEquals($contract,[type]::GetType($contract.FullName,$true))){$sameCanonical=$false}};$distinct=-not [object]::ReferenceEquals($first,$second);if($first.Length -gt 0){$first[0]=$null};$third=$type.GetInterfaces();$inventories.Add([ordered]@{type=$typeName;names=$names;distinctArrays=$distinct;afterMutation=@($third|ForEach-Object FullName);canonicalElements=$sameCanonical})
 foreach($query in $plan.names){foreach($route in $plan.routes){$parameters=[type[]]@([string]);if($route -ne 'default'){$parameters=[type[]]@([string],[bool])};$method=$type.GetType().GetMethod('GetInterface',$parameters);$arguments=[object[]]::new($parameters.Count);$arguments[0]=$query;if($parameters.Count -eq 2){$arguments[1]=$route -eq 'ignore-case'};try{$found=$method.Invoke($type,$arguments);$result=[ordered]@{ok=$true;value=$(if($null -eq $found){$null}else{$found.FullName})}}catch{$result=Failure $_};$rows.Add([ordered]@{type=$typeName;query=$query;route=$route;result=$result})}}
}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';inventories=$inventories.ToArray();rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 18 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS cross-type interface name lookup: $($rows.Count) calls and 31 reference inventories"
